// PRODUCTION YEARS FROM THE DAILY VROOM IMPORT CALCULATOR (Sam, Oct 29 2026). The taxonomy's year_ranges are missing for many models; the calculator's year, make and model list
// (the dailyvroom-calculator repo, index.html CAR_MODELS: [model, firstYear, lastYear] per make, snapshot in data/calculatorModelYears.json, regenerated by scripts/importCalculatorYears.mjs)
// fills them. A taxonomy model takes the span of every calculator entry that is that name or starts with it as a whole word ("Corvette" = Corvette C1 to C8; "911" = 911 Carrera, 911 Turbo ...).
// Used only when neither the taxonomy nor a curated production rule has years for the model.
import fs from "node:fs";
let DATA = null;
function load() {
  if (DATA) return DATA;
  try { DATA = JSON.parse(fs.readFileSync(new URL("../data/calculatorModelYears.json", import.meta.url), "utf8")).makes || {}; } catch { DATA = {}; }
  return DATA;
}
// Chip-only overrides where the calculator's own span is wider than the nameplate's life (it lists the 1960 to 1987 C10 pickups as "Silverado 1500 C10"). Used by the Which-model question only,
// never by the typed-words year check: Sam, Oct 29 2026, "1969 chevrolet can never offer Silverado".
// Each is a naming oddity in the calculator's list, posted in lane notes (Oct 29 2026):
//   chevrolet|silverado  the calculator lists the 1960 to 1987 C10 pickups as "Silverado 1500 C10" and the 1988 to 1998 trucks as "Silverado C/K"; the Silverado nameplate is the 1999 on truck (Sam: yes).
//   dodge|daytona        the calculator says 1992 to 2005; the Daytona hatchback sold 1984 to 1993 (the 1969 Charger Daytona is its own model).
const CHIP_OVERRIDES = { "chevrolet|silverado": [[1999, 2026]], "dodge|daytona": [[1984, 1993]] };
export function chipYearOverride(make, model) { return CHIP_OVERRIDES[makeKey(make) + "|" + norm(model)] || null; }
const norm = s => String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
function makeKey(s) { return norm(s).replace(/ /g, ""); }
export function calculatorYearsFor(make, model) {
  const d = load(), mk = Object.keys(d).find(k => makeKey(k) === makeKey(make) || (makeKey(make) === "mercedesbenz" && makeKey(k) === "mercedes"));
  if (!mk) return null;
  const want = norm(model); if (!want) return null;
  const hits = d[mk].filter(([name]) => { const n = norm(name); return n === want || n.startsWith(want + " "); });
  if (!hits.length) return null;
  return mergeRanges(hits.map(h => [h[1], h[2]]));
}
// the union of the spans, not the first to the last: a Supra sold 1981 to 2002 and again from 2019 was in production in 2010 on a min to max
export function mergeRanges(list) {
  const s = [...list].filter(r => Array.isArray(r) && r.length === 2).sort((a, b) => a[0] - b[0]), out = [];
  for (const r of s) { const last = out[out.length - 1]; if (last && r[0] <= last[1] + 1) last[1] = Math.max(last[1], r[1]); else out.push([r[0], r[1]]); }
  return out;
}
